 const filters=`<label>${bridge.t('Rating')}<select data-admin-filter="rating">${option('','All ratings',rating)}${[5,4,3,2,1].map(value=>option(String(value),`${value} ${bridge.t('stars')}`,rating)).join('')}</select></label><label>${bridge.t('Report status')}<select data-admin-filter="reported">${option('','All reviews',reported)}${option('Reported','Reported',reported)}${option('Not reported','Not reported',reported)}</select></label><label>${bridge.t('Moderation status')}<select data-admin-filter="moderation">${option('','All statuses',moderation)}${['Visible','Hidden'].map(value=>option(value,value,moderation)).join('')}</select></label>`;
