 return `${summary}${sectionToolbar('Search product, customer, shop, or review text',filters,`${option('recent','Newest first',ui.sort)}${option('rating-high','Highest rating',ui.sort)}${option('rating-low','Lowest rating',ui.sort)}`)}${table(['Product','Customer','Rating','Review','Reported','Moderation status','Date','Actions'],items,empty('No reviews match','Try another search or adjust the review filters.'))}${page.foot}`;
